$HistoryLength=0;
$Assumptions=True;
gate[name_,test_]:=If[TrueQ[test],Print["PASS ",name],Print["GATE_FAILURE ",name];Quit[1]];
held=ToExpression[ReadString["/u/scratch/r/rushil/AI_Assisted_SIDIS/Hgq_v4_20260906/s09_laurent_unreduced_179183.wl"],InputForm,HoldComplete];
field[name_]:=ReleaseHold[First[Cases[held,HoldPattern[Rule[name,v_]]:>HoldComplete[v],Infinity]]];
task=field["Task"];assumptions=field["Assumptions"];
input=Get["/u/scratch/r/rushil/AI_Assisted_SIDIS/Hgq_v4_20260906/s05_result.wl"];angular=Get["/u/scratch/r/rushil/AI_Assisted_SIDIS/Hgq_v4_20260906/s06_result.wl"];
physical=input["PhysicalRegion"]&&mu>0&&SUNN>1&&B>0;
geometry[mode_, i_, j_] := geometry[mode, i, j] = Module[{first, second, cosine, keyType},
  {first, second} = input["Basis"][mode]["Geometry"][[{i, j}]];
  cosine = FullSimplify[first["Direction"].second["Direction"], physical];
  If[first["Massless"] && second["Massless"],
    <|"Type" -> "LL", "Reverse" -> False, "Scale" -> {first["Scale"], second["Scale"]},
      "Rules" -> {z -> Factor[(1 + cosine)/2]}|>,
    gate["one mixed denominator is massive", Xor[first["Massless"], second["Massless"]]];
    <|"Type" -> "ML", "Reverse" -> first["Massless"],
      "Scale" -> {first["Scale"], second["Scale"]},
      "Rules" -> {d -> If[first["Massless"], second, first]["d"], c -> cosine}|>]];

valuation[value_] := Module[{rational = Factor[value]},
  gate["endpoint valuation is rational", PolynomialQ[Numerator[rational], s23] &&
    PolynomialQ[Denominator[rational], s23]];
  Exponent[Numerator[rational], s23, Min] - Exponent[Denominator[rational], s23, Min]];
branchAssumptions[sign_] := Q2 > 0 && s > 0 && omega > 0 && mu > 0 && SUNN > 1 &&
  B > 0 && -Q2 - s < sign omega - s < 0;
softGeometry[map_, sign_] := softGeometry[map, sign] = FullSimplify[
  map["Rules"] /. t -> sign omega - s,
  branchAssumptions[sign] && s23 > 0 && (input["PhysicalRegion"] /. t -> sign omega - s)];
softMassiveLimit[rules_, sign_] := softMassiveLimit[rules, sign] = FullSimplify[
  Limit[d /. rules, s23 -> 0], branchAssumptions[sign]];


signs=Select[{1,-1},branchAssumptions[#]===assumptions&];
gate["saved branch identified",Length[signs]===1];
sign=First[signs];
term=input["Basis"][task[[1]]]["Terms"][[task[[2]]]];
map=geometry[task[[1]],term[[1]],term[[2]]];
powers=term[[{3,4}]];
prefactor=Factor[(term[[5]]/.D->4-2 eps) Times@@(map["Scale"]^(-powers))/.t->sign omega-s];
If[map["Reverse"],powers=Reverse[powers]];
key=Prepend[powers,map["Type"]];
value=SelectFirst[angular["Masters"],#["Key"]===key&]["Value"]["Regular"];
rules=softGeometry[map,sign];
end=FullSimplify[Limit[c/.rules,s23->0,Direction->"FromAbove",Assumptions->assumptions],assumptions];
Print["MASTER DATA ",InputForm[{task,key,end}]];
dEnd=softMassiveLimit[rules,sign];
Print["MASSIVE ENDPOINT ",InputForm[dEnd]];
gate["massive endpoint is finite and separated",FreeQ[dEnd,_Limit|_ConditionalExpression|Indeterminate|_DirectedInfinity]&&FullSimplify[dEnd>1,assumptions]];
gate["mixed master with an angular endpoint",map["Type"]==="ML"&&MemberQ[{-1,1},end]];
directions=Select[{"FromAbove"->(c>end),"FromBelow"->(c<end)},FullSimplify[Last[#],-1<c<1]===True&];
gate["angular approach direction derived",Length[directions]===1];
direction=First[First[directions]];
domain=d>1&&-1<c<1;
inverseSum=PolyLog[2,x]+PolyLog[2,1/x];
inverseSlope=FullSimplify[FunctionExpand[D[inverseSum,x]],x<0];
primitive=Integrate[inverseSlope,x,Assumptions->x<0,GenerateConditions->False];
inverseConstant=FullSimplify[(inverseSum-primitive)/.x->-1];
inverseFormula=FullSimplify[primitive+inverseConstant,x<0];
gate["dilogarithm inversion derived from its derivative and anchor",
 FreeQ[inverseFormula,_Integrate|_ConditionalExpression]&&
 FullSimplify[D[inverseSum-inverseFormula,x],x<0]===0&&
 FullSimplify[(inverseSum-inverseFormula)/.x->-1]===0];
Print["INVERSION FORMULA ",InputForm[inverseFormula]];
arguments=DeleteDuplicates[Cases[value,PolyLog[2,arg_]:>arg,Infinity]];
inversionArguments=Select[arguments,
 Limit[#,c->end,Direction->direction,Assumptions->d>1]===-Infinity&];
gate["inverted arguments have proved negative real domain",
 And@@(FullSimplify[#<0,domain]&/@inversionArguments)];
Print["INVERTED ARGUMENTS ",InputForm[inversionArguments]];
transformed=value/.Table[PolyLog[2,arg]->((inverseFormula/.x->arg)-PolyLog[2,Cancel[1/arg]]),{arg,inversionArguments}];
transformed=transformed/.a_ArcCoth:>FunctionExpand[a,domain];
logObjects=DeleteDuplicates[Cases[transformed,_Log,Infinity]];
logRules=Table[obj->PowerExpand[obj/.Log[arg_]:>Log[Factor[arg]],Assumptions->domain],{obj,logObjects}];
transformed=Expand[transformed/.logRules];
functions=DeleteDuplicates[Cases[transformed,_Log|_PolyLog,Infinity]];
transformed=Collect[transformed,functions,Factor];
Print["TRANSFORMED MASTER ",InputForm[transformed]];
Do[
 coeff=Coefficient[Expand[transformed],eps,order];
 result=MemoryConstrained[TimeConstrained[
 Limit[coeff,c->end,Direction->direction,Assumptions->d>1],60,$TimedOut],1024^3,$Failed];
 Print["COEFFICIENT LIMIT ",order," ",InputForm[result]];
 gate["coefficient endpoint finite",FreeQ[result,$Failed|$TimedOut|_Limit|_DirectedInfinity|Indeterminate]];
,{order,-1,1}];
phase=mu^(2 eps) 2^(-2) Pi^(-eps) Gamma[1-eps]/((2Pi)^(2-2eps) Gamma[1-2eps]);
Print["BEGIN TRANSFORMED RECOIL SERIES"];
recoil=MemoryConstrained[TimeConstrained[
 Series[phase prefactor (transformed/.rules),{s23,0,-1},Assumptions->assumptions&&s23>0],
 240,(Print["CHECK_TIMEOUT"];Quit[1])],1024^3,(Print["CHECK_MEMORY_LIMIT"];Quit[1])];
Print["RECOIL HEAD ",Head[recoil]];
gate["transformed recoil expansion has complete Laurent order",
 recoil===0||(Head[recoil]===SeriesData&&recoil[[6]]===1&&recoil[[5]]> -1)];
If[Head[recoil]===SeriesData,Print["RECOIL RANGE ",InputForm[{recoil[[4]],recoil[[5]],recoil[[6]]}]]];
Print["CHECK_DONE"];
Quit[];
